    43	    public void register(Javalin app) {
    44	        app.exception(PousadaException.class, (e, ctx) -> error(ctx, e.code().httpStatus(), e.code().name(), e.getMessage()));
    45	        app.exception(Exception.class, (e, ctx) -> {
    46	            e.printStackTrace();
    47	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    48	        });
    49	
    50	        app.get("/rooms", ctx -> json(ctx, 200, rooms.all().stream().map(this::roomView).toList()));
    51	        app.post("/reservations", ctx -> json(ctx, 201, view(reservations.create(parseNewReservation(ctx)))));
    52	        app.get("/reservations/{id}", ctx -> json(ctx, 200, view(reservations.get(id(ctx)))));
    53	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, view(reservations.confirm(id(ctx)))));
    54	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, view(reservations.cancel(id(ctx)))));
    55	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, view(reservations.checkIn(id(ctx)))));
    56	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, receiptView(reservations.checkOut(id(ctx)))));
    57	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, receiptView(reservations.document(id(ctx)))));
    58	        app.get("/messages", ctx -> json(ctx, 200, messages.findAll().stream().map(m -> {
    59	            Map<String, Object> v = new LinkedHashMap<>();
    60	            v.put("id", m.id());
    61	            v.put("channel", m.channel());
    62	            v.put("to", m.to());
    63	            v.put("subject", m.subject());
    64	            v.put("body", m.body());
    65	            return v;
    66	        }).toList()));
    67	        app.get("/reports/occupancy", ctx ->
    68	                csv(ctx, reports.occupancy(queryParam(ctx, "date", LocalDate::parse))));
    69	        app.get("/reports/revenue", ctx ->
    70	                csv(ctx, reports.revenue(queryParam(ctx, "month", YearMonth::parse))));
    71	    }
