    73	    private NewReservation parseNewReservation(Context ctx) {
    74	        JsonNode body;
    75	        try {
    76	            body = mapper.readTree(ctx.body());
    77	        } catch (JsonProcessingException e) {
    78	            throw invalid("O corpo não é um JSON válido");
    79	        }
    80	        if (body == null || !body.isObject()) {
    81	            throw invalid("O corpo deve ser um objeto JSON");
    82	        }
    83	        int roomNumber = integer(body, "roomNumber");
    84	        String name = text(body, "guestName");
    85	        String email = text(body, "guestEmail");
    86	        String cpf = text(body, "guestCpf");
    87	        LocalDate checkIn = date(body, "checkIn");
    88	        LocalDate checkOut = date(body, "checkOut");
    89	        int guests = integer(body, "guests");
    90	        RatePlan plan = ratePlan(body);
    91	        if (!checkOut.isAfter(checkIn)) {
    92	            throw invalid("A saída deve ser depois da entrada");
    93	        }
    94	        if (guests < 1) {
    95	            throw invalid("É preciso ao menos um hóspede");
    96	        }
    97	        return new NewReservation(roomNumber, name, email, cpf, checkIn, checkOut, guests, plan);
    98	    }
    99	
   100	    private static String text(JsonNode body, String field) {
   101	        JsonNode n = body.get(field);
   102	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
   103	            throw invalid("Campo '" + field + "' ausente ou inválido");
   104	        }
   105	        return n.asText();
   106	    }
   107	
   108	    private static int integer(JsonNode body, String field) {
   109	        JsonNode n = body.get(field);
   110	        if (n == null || !n.isInt()) {
   111	            throw invalid("Campo '" + field + "' ausente ou inválido");
   112	        }
   113	        return n.asInt();
   114	    }
   115	
   116	    private static LocalDate date(JsonNode body, String field) {
   117	        try {
   118	            return LocalDate.parse(text(body, field));
   119	        } catch (DateTimeParseException e) {
   120	            throw invalid("Campo '" + field + "' deve estar no formato AAAA-MM-DD");
   121	        }
   122	    }
   123	
   124	    private static RatePlan ratePlan(JsonNode body) {
   125	        try {
   126	            return RatePlan.valueOf(text(body, "ratePlan"));
   127	        } catch (IllegalArgumentException e) {
   128	            throw invalid("Campo 'ratePlan' deve ser STANDARD ou NON_REFUNDABLE");
   129	        }
   130	    }
   131	
   132	    private static <T> T queryParam(Context ctx, String name, Function<String, T> parser) {
   133	        String value = ctx.queryParam(name);
   134	        if (value == null) {
   135	            throw invalid("Parâmetro '" + name + "' ausente");
   136	        }
   137	        try {
   138	            return parser.apply(value);
   139	        } catch (DateTimeParseException e) {
   140	            throw invalid("Parâmetro '" + name + "' em formato inválido");
   141	        }
   142	    }
   143	
   144	    private static long id(Context ctx) {
   145	        String raw = ctx.pathParam("id");
   146	        try {
   147	            return Long.parseLong(raw);
   148	        } catch (NumberFormatException e) {
   149	            throw new PousadaException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + raw + " não existe");
   150	        }
   151	    }
   152	
   153	    private static PousadaException invalid(String message) {
   154	        return new PousadaException(ErrorCode.INVALID_REQUEST, message);
   155	    }
