   166	    private Map<String, Object> view(Reservation r) {
   167	        Map<String, Object> v = new LinkedHashMap<>();
   168	        v.put("id", r.id());
   169	        v.put("roomNumber", r.roomNumber());
   170	        v.put("guestName", r.guestName());
   171	        v.put("guestEmail", r.guestEmail());
   172	        v.put("guestCpf", r.guestCpf());
   173	        v.put("checkIn", r.checkIn().toString());
   174	        v.put("checkOut", r.checkOut().toString());
   175	        v.put("guests", r.guests());
   176	        v.put("ratePlan", r.ratePlan());
   177	        v.put("nights", r.quote().nights());
   178	        v.put("subtotal", r.quote().subtotal());
   179	        v.put("discount", r.quote().discount());
   180	        v.put("total", r.quote().total());
   181	        v.put("status", r.status());
   182	        v.put("amountPaid", r.amountPaid());
