   186	
   187	    private Map<String, Object> receiptView(Receipt c) {
   188	        Map<String, Object> v = new LinkedHashMap<>();
   189	        v.put("title", c.title());
   190	        v.put("reservationId", c.reservationId());
   191	        v.put("guestName", c.guestName());
   192	        v.put("guestCpf", c.guestCpf());
   193	        v.put("roomNumber", c.roomNumber());
   194	        v.put("roomType", c.roomType());
   195	        v.put("checkIn", c.checkIn().toString());
   196	        v.put("checkOut", c.checkOut().toString());
   197	        v.put("nights", c.nights());
   198	        v.put("subtotal", c.subtotal());
   199	        v.put("discount", c.discount());
   200	        v.put("total", c.total());
   201	        return v;
   202	    }
   203	
   204	    private void json(Context ctx, int status, Object body) {
   205	        try {
   206	            ctx.status(status).contentType("application/json").result(mapper.writeValueAsString(body));
   207	        } catch (JsonProcessingException e) {
   208	            throw new IllegalStateException(e);
   209	        }
   210	    }
   211	
   212	    private void error(Context ctx, int status, String code, String message) {
   213	        Map<String, Object> v = new LinkedHashMap<>();
   214	        v.put("error", code);
   215	        v.put("message", message);
   216	        json(ctx, status, v);
   217	    }
   218	
   219	    private static void csv(Context ctx, String body) {
   220	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
   221	    }
   222	}
