     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	import java.time.YearMonth;
    12	import java.util.List;
    13	
    14	public final class ReportService {
    15	    private final Database db;
    16	    private final ReservationRepository reservations;
    17	    private final RoomCatalog rooms;
    18	
    19	    public ReportService(Database db, ReservationRepository reservations, RoomCatalog rooms) {
    20	        this.db = db;
    21	        this.reservations = reservations;
    22	        this.rooms = rooms;
    23	    }
    24	
    25	    public String occupancy(LocalDate night) {
    26	        List<Reservation> occupying = db.transaction(() -> reservations.findPaidOccupying(night));
    27	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    28	        for (Reservation r : occupying) {
    29	            csv.append(String.join(",", String.valueOf(r.roomNumber()), rooms.require(r.roomNumber()).type().name(),
    30	                    String.valueOf(r.id()), r.checkIn().toString(), r.checkOut().toString())).append('\n');
    31	        }
    32	        // um quarto só pode ter uma reserva por noite, então cada linha é um quarto ocupado
    33	        return csv.append("total,").append(occupying.size()).append('/').append(rooms.size()).append('\n')
    34	                .toString();
    35	    }
    36	
    37	    public String revenue(YearMonth month) {
    38	        List<Reservation> kept = db.transaction(() ->
    39	                reservations.findRetainingMoney(month.atDay(1), month.plusMonths(1).atDay(1)));
    40	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    41	        BigDecimal total = Money.ZERO;
    42	        for (Reservation r : kept) {
    43	            csv.append(String.join(",", String.valueOf(r.id()), String.valueOf(r.roomNumber()),
    44	                    r.checkIn().toString(), r.checkOut().toString(), r.status().name(),
    45	                    Money.plain(r.retained()))).append('\n');
    46	            total = total.add(r.retained());
    47	        }
    48	        return csv.append("total,").append(Money.plain(total)).append('\n').toString();
    49	    }
    50	}
