     8	import com.marealta.domain.Room;
     9	import com.marealta.domain.RoomCatalog;
    10	import com.marealta.events.ReservationEvent;
    11	import com.marealta.events.ReservationListener;
    12	import com.marealta.persistence.Database;
    13	import com.marealta.persistence.ReservationRepository;
    14	
    15	import java.util.List;
    16	import java.util.function.Consumer;
    17	
    18	public final class ReservationService {
    19	    private final Database db;
    20	    private final ReservationRepository reservations;
    21	    private final RoomCatalog rooms;
    22	    private final List<ReservationListener> listeners;
    23	
    24	    public ReservationService(Database db, ReservationRepository reservations, RoomCatalog rooms,
    25	                              List<ReservationListener> listeners) {
    26	        this.db = db;
    27	        this.reservations = reservations;
    28	        this.rooms = rooms;
    29	        this.listeners = List.copyOf(listeners);
    30	    }
    31	
    32	    public Reservation create(NewReservation cmd) {
    33	        return db.transaction(() -> {
    34	            Room room = rooms.require(cmd.roomNumber());
    35	            if (cmd.guests() > room.capacity()) {
    36	                throw new PousadaException(ErrorCode.CAPACITY_EXCEEDED,
    37	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    38	            }
    39	            reservations.lockBookings();
    40	            if (reservations.isRoomBooked(room.number(), cmd.checkIn(), cmd.checkOut())) {
    41	                throw new PousadaException(ErrorCode.ROOM_UNAVAILABLE,
    42	                        "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    43	            }
    44	            Reservation r = Reservation.open(room, cmd.guestName(), cmd.guestEmail(), cmd.guestCpf(),
    45	                    cmd.checkIn(), cmd.checkOut(), cmd.guests(), cmd.ratePlan());
    46	            reservations.insert(r);
    47	            return r;
    48	        });
    49	    }
    50	
    51	    public Reservation get(long id) {
    52	        return db.transaction(() -> load(id, false));
    53	    }
    54	
    55	    public Reservation confirm(long id) {
    56	        return change(id, Reservation::confirm, ReservationEvent.Type.CONFIRMED);
    57	    }
    58	
    59	    public Reservation cancel(long id) {
    60	        return change(id, Reservation::cancel, ReservationEvent.Type.CANCELLED);
    61	    }
    62	
    63	    public Reservation checkIn(long id) {
    64	        return change(id, Reservation::registerCheckIn, ReservationEvent.Type.CHECKED_IN);
    65	    }
    66	
    67	    public Receipt checkOut(long id) {
    68	        Reservation r = change(id, Reservation::registerCheckOut, ReservationEvent.Type.CHECKED_OUT);
    69	        return Receipt.of(r, rooms.require(r.roomNumber()));
    70	    }
    71	
    72	    /** Segunda via do comprovante: só existe para reserva paga. */
    73	    public Receipt document(long id) {
    74	        return db.transaction(() -> {
    75	            Reservation r = load(id, false);
    76	            if (!r.status().isPaid()) {
    77	                throw new PousadaException(ErrorCode.OPERATION_NOT_ALLOWED,
    78	                        "O comprovante só existe para reserva paga");
    79	            }
    80	            return Receipt.of(r, rooms.require(r.roomNumber()));
    81	        });
    82	    }
    83	
    84	    /** A sequência é a mesma para toda mudança: trancar, mudar, gravar e avisar quem quer saber. */
    85	    private Reservation change(long id, Consumer<Reservation> change, ReservationEvent.Type type) {
    86	        return db.transaction(() -> {
    87	            Reservation r = load(id, true);
    88	            ReservationStatus previous = r.status();
    89	            change.accept(r);
    90	            reservations.update(r);
    91	            ReservationEvent event = new ReservationEvent(type, r, rooms.require(r.roomNumber()), previous);
    92	            listeners.forEach(l -> l.onEvent(event));
    93	            return r;
    94	        });
    95	    }
    96	
    97	    private Reservation load(long id, boolean lock) {
    98	        return (lock ? reservations.findForUpdate(id) : reservations.find(id)).orElseThrow(() ->
    99	                new PousadaException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe"));
   100	    }
   101	}

