     1	package com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	/** Preço de uma estadia: noites, soma das noites, desconto e total. */
     8	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    10	
    11	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    12	        BigDecimal subtotal = Money.ZERO;
    13	        int nights = 0;
    14	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    15	            subtotal = subtotal.add(nightPrice(room, night));
    16	            nights++;
    17	        }
    18	        BigDecimal discount = plan.discount(subtotal);
    19	        return new Quote(nights, subtotal, discount, Money.of(subtotal.subtract(discount)));
    20	    }
    21	
    22	    private static BigDecimal nightPrice(Room room, LocalDate night) {
    23	        if (!isHighSeason(night)) {
    24	            return room.nightlyRate();
    25	        }
    26	        return Money.of(room.nightlyRate().multiply(HIGH_SEASON_FACTOR));
    27	    }
    28	
    29	    /** De 15 de dezembro ao fim de fevereiro, e julho inteiro. */
    30	    static boolean isHighSeason(LocalDate night) {
    31	        Month month = night.getMonth();
    32	        return month == Month.JULY
    33	                || month == Month.JANUARY
    34	                || month == Month.FEBRUARY
    35	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    36	    }
    37	}
