 12	
 13	public final class MessageRepository implements MessageOutbox {
 14	    private final Database db;
 15	
 16	    public MessageRepository(Database db) {
 17	        this.db = db;
 18	    }
 19	
 20	    @Override
 21	    public void send(Channel channel, String to, String subject, String body) {
 22	        db.transaction(() -> {
 23	            try (PreparedStatement ps = db.connection().prepareStatement(
 24	                    "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)")) {
 25	                ps.setString(1, channel.name());
 26	                ps.setString(2, to);
 27	                ps.setString(3, subject);
 28	                ps.setString(4, body);
 29	                ps.executeUpdate();
 30	                return null;
 31	            } catch (SQLException e) {
 32	                throw new UncheckedSqlException(e);
 33	            }
 34	        });
 35	    }
 36	
 37	    public List<Message> findAll() {
 38	        return db.transaction(() -> {
 39	            try (PreparedStatement ps = db.connection().prepareStatement(
 40	                    "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
 41	                 ResultSet rs = ps.executeQuery()) {
 42	                List<Message> list = new ArrayList<>();
 43	                while (rs.next()) {
 44	                    list.add(new Message(rs.getLong("id"), Channel.valueOf(rs.getString("channel")),
 45	                            rs.getString("recipient"), rs.getString("subject"), rs.getString("body")));
 46	                }
 47	                return list;
 48	            } catch (SQLException e) {
 49	                throw new UncheckedSqlException(e);
 50	            }
 51	        });
 52	    }
 53	}
