 19	public final class ReservationRepository {
 20	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, "
 21	            + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
 22	
 23	    private final Database db;
 24	
 25	    public ReservationRepository(Database db) {
 26	        this.db = db;
 27	    }
 28	
 29	    /** Serializa as criações de reserva, para que a checagem de quarto livre valha até o insert. */
 30	    public void lockBookings() {
 31	        run("SELECT pg_advisory_xact_lock(7070)", ps -> {
 32	            ps.execute();
 33	            return null;
 34	        });
 35	    }
 36	
 37	    public void insert(Reservation r) {
 38	        long id = run("INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
 39	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
 40	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", Statement.RETURN_GENERATED_KEYS, ps -> {
 41	            ps.setInt(1, r.roomNumber());
 42	            ps.setString(2, r.guestName());
 43	            ps.setString(3, r.guestEmail());
 44	            ps.setString(4, r.guestCpf());
 45	            ps.setDate(5, Date.valueOf(r.checkIn()));
 46	            ps.setDate(6, Date.valueOf(r.checkOut()));
 47	            ps.setInt(7, r.guests());
 48	            ps.setString(8, r.ratePlan().name());
 49	            ps.setInt(9, r.quote().nights());
 50	            ps.setBigDecimal(10, r.quote().subtotal());
 51	            ps.setBigDecimal(11, r.quote().discount());
 52	            ps.setBigDecimal(12, r.quote().total());
 53	            ps.setString(13, r.status().name());
 54	            ps.setBigDecimal(14, r.amountPaid());
 55	            ps.setBigDecimal(15, r.refund());
 56	            ps.executeUpdate();
 57	            try (ResultSet keys = ps.getGeneratedKeys()) {
 58	                keys.next();
 59	                return keys.getLong(1);
 60	            }
 61	        });
 62	        r.assignId(id);
 63	    }
 64	
 65	    public void update(Reservation r) {
 66	        run("UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?", ps -> {
 67	            ps.setString(1, r.status().name());
 68	            ps.setBigDecimal(2, r.amountPaid());
 69	            ps.setBigDecimal(3, r.refund());
 70	            ps.setLong(4, r.id());
 71	            ps.executeUpdate();
 72	            return null;
 73	        });
 74	    }
 75	
 76	    public Optional<Reservation> find(long id) {
 77	        return query("SELECT " + COLUMNS + " FROM reservations WHERE id = ?", ps -> ps.setLong(1, id))
 78	                .stream().findFirst();
 79	    }
 80	
 81	    /** Busca trancando a linha, para que operações simultâneas na mesma reserva se enfileirem. */
 82	    public Optional<Reservation> findForUpdate(long id) {
 83	        return query("SELECT " + COLUMNS + " FROM reservations WHERE id = ? FOR UPDATE", ps -> ps.setLong(1, id))
 84	                .stream().findFirst();
 85	    }
 86	
 87	    /** Há reserva não cancelada do quarto em alguma das noites [checkIn, checkOut)? */
 88	    public boolean isRoomBooked(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
 89	        return !query("SELECT " + COLUMNS + " FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
 90	                + "AND check_in < ? AND check_out > ? LIMIT 1", ps -> {
 91	            ps.setInt(1, roomNumber);
 92	            ps.setDate(2, Date.valueOf(checkOut));
 93	            ps.setDate(3, Date.valueOf(checkIn));
 94	        }).isEmpty();
 95	    }
 96	
 97	    /** Reservas pagas que ocupam um quarto na noite indicada, por número do quarto. */
 98	    public List<Reservation> findPaidOccupying(LocalDate night) {
 99	        return query("SELECT " + COLUMNS + " FROM reservations WHERE status IN ('CONFIRMED', 'CHECKED_IN', "
100	                + "'CHECKED_OUT') AND check_in <= ? AND check_out > ? ORDER BY room_number, id", ps -> {
101	            ps.setDate(1, Date.valueOf(night));
102	            ps.setDate(2, Date.valueOf(night));
103	        });
104	    }
105	
106	    /** Reservas com entrada em [from, until) que deixaram dinheiro com a pousada. */
107	    public List<Reservation> findRetainingMoney(LocalDate from, LocalDate until) {
108	        return query("SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
109	                + "AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id", ps -> {
110	            ps.setDate(1, Date.valueOf(from));
111	            ps.setDate(2, Date.valueOf(until));
112	        });
113	    }
