115	    private interface Binder {
116	        void bind(PreparedStatement ps) throws SQLException;
117	    }
118	
119	    private interface Action<T> {
120	        T apply(PreparedStatement ps) throws SQLException;
121	    }
122	
123	    private <T> T run(String sql, Action<T> action) {
124	        return run(sql, Statement.NO_GENERATED_KEYS, action);
125	    }
126	
127	    private <T> T run(String sql, int keys, Action<T> action) {
128	        try (PreparedStatement ps = db.connection().prepareStatement(sql, keys)) {
129	            return action.apply(ps);
130	        } catch (SQLException e) {
131	            throw new UncheckedSqlException(e);
132	        }
133	    }
134	
135	    private List<Reservation> query(String sql, Binder binder) {
136	        return run(sql, ps -> {
137	            binder.bind(ps);
138	            try (ResultSet rs = ps.executeQuery()) {
139	                List<Reservation> list = new ArrayList<>();
140	                while (rs.next()) {
141	                    list.add(map(rs));
142	                }
143	                return list;
144	            }
145	        });
146	    }
